use App\Filament\Resources\CrmOfferResource; use App\Filament\Resources\CrmOfferResource\RelationManagers\{OfferApprovalsRelationManager, OfferRevisionsRelationManager}; use Filament\Actions; use Filament\Infolists\Infolist; use Filament\Resources\Pages\ViewRecord;
class ViewCrmOffer extends ViewRecord { protected static string $resource = CrmOfferResource::class; public function getTitle(): string { return $this->record->reference_number; } protected function getHeaderActions(): array { return [Actions\EditAction::make()->label(__('crm.actions.edit'))]; } public function getRelationManagers(): array { return [OfferRevisionsRelationManager::class, OfferApprovalsRelationManager::class]; } public function infolist(Infolist $infolist): Infolist { return CrmOfferResource::infolist($infolist); } }
